import{_ as i,C as r,c as p,o as n,j as a,a8 as s,a as e,G as l}from"./chunks/framework.DBQiK-q5.js";const d="/sealdice-manual-next/assets/platform-qq-bot-qrcode.CZVWW4Rf.jpg",m="/sealdice-manual-next/assets/platform-qq-official-1.xvYBQLAg.png",c="/sealdice-manual-next/assets/platform-qq-official-2.BG1tRARH.png",f="/sealdice-manual-next/assets/platform-qq-official-4.DeNeyeyZ.png",u="/sealdice-manual-next/assets/platform-qq-official-3.DhHb4kkJ.png",Q="/sealdice-manual-next/assets/platform-qq-official-11.CAwk7sBV.png",q="/sealdice-manual-next/assets/platform-qq-official-12.CdZ1iKI7.png",b="/sealdice-manual-next/assets/platform-qq-official-7.B2ZAvwsL.png",h="/sealdice-manual-next/assets/platform-qq-official-8.DhuF29we.png",g="/sealdice-manual-next/assets/platform-qq-official-6.D_U8yZ10.png",k="/sealdice-manual-next/assets/platform-qq-official-5.CdDG8A97.png",x="/sealdice-manual-next/assets/platform-qq-official-9.DBxQzTd1.png",I=JSON.parse('{"title":"QQ 官方机器人","description":"","frontmatter":{"lang":"zh-cn","title":"QQ 官方机器人"},"headers":[],"relativePath":"deploy/platform-qq-official.md","filePath":"deploy/platform-qq-official.md","lastUpdated":1787636036000}'),A={name:"deploy/platform-qq-official.md"},_={id:"qq-官方机器人",tabindex:"-1"},B={class:"tip custom-block"},P={id:"连接海豹",tabindex:"-1"};function E(v,t,C,w,T,S){const o=r("Badge");return n(),p("div",null,[a("h1",_,[t[0]||(t[0]=e("QQ 官方机器人 ",-1)),l(o,{type:"tip",text:"v1.6.0"}),t[1]||(t[1]=e()),t[2]||(t[2]=a("a",{class:"header-anchor",href:"#qq-官方机器人","aria-label":'Permalink to "QQ 官方机器人 <Badge type="tip" text="v1.6.0" />"'},"​",-1))]),a("p",null,[t[3]||(t[3]=e("海豹从 ",-1)),l(o,{type:"tip",text:"v1.4.2"}),t[4]||(t[4]=e(" 开始支持对接 QQ 官方的机器人服务。",-1))]),t[17]||(t[17]=a("div",{class:"info custom-block"},[a("p",{class:"custom-block-title"},"本节内容"),a("p",null,"本节将包含你在 QQ 官方机器人平台接入海豹核心需要了解的特定内容。")],-1)),a("div",B,[t[9]||(t[9]=a("p",{class:"custom-block-title"},"提示：QQ 机器人",-1)),t[10]||(t[10]=a("p",null,[e("QQ 官方目前已开放了机器人功能，可进入 "),a("a",{href:"https://q.qq.com/#/",target:"_blank",rel:"noreferrer"},"QQ 开放平台"),e(" 进行申请。")],-1)),t[11]||(t[11]=a("p",null,[e("搭建机器人官方请参考 "),a("a",{href:"https://bot.q.qq.com/wiki/#/",target:"_blank",rel:"noreferrer"},"QQ 机器人文档"),e("。")],-1)),t[12]||(t[12]=a("p",null,"QQ 官方机器人的开放范围、审核要求和接口能力可能调整，请以开放平台显示的内容为准。",-1)),a("p",null,[t[5]||(t[5]=e("从海豹 ",-1)),l(o,{type:"tip",text:"v1.6.0"}),t[6]||(t[6]=e(" 开始，官方机器人适配已支持普通 QQ 群消息、C2C 单聊、群内非 ",-1)),t[7]||(t[7]=a("code",null,"@",-1)),t[8]||(t[8]=e(" 消息、WebSocket 和 Webhook。频道、群聊和单聊能够使用的事件及发送能力仍受应用权限和 QQ 官方接口限制，不能假定与普通 QQ 账号完全一致。",-1))]),t[13]||(t[13]=a("p",null,"QQ 官方机器人的优点，就是不用担心被风控。",-1))]),t[18]||(t[18]=s('<h2 id="尝试一下" tabindex="-1">尝试一下 <a class="header-anchor" href="#尝试一下" aria-label="Permalink to &quot;尝试一下&quot;">​</a></h2><p>如果你想尝试一下这样的机器人，非常欢迎你使用海豹官方的骰子：</p><img src="'+d+'" alt="海豹机器人二维码" width="65%"><h2 id="获取连接所需信息" tabindex="-1">获取连接所需信息 <a class="header-anchor" href="#获取连接所需信息" aria-label="Permalink to &quot;获取连接所需信息&quot;">​</a></h2><p>要获取用于连接海豹的信息之前，你需要建立好一个 QQ 机器人应用。可前往 <a href="https://q.qq.com/#/" target="_blank" rel="noreferrer">QQ 开放平台</a> 进行申请，<strong>实名</strong>注册后，创建一个机器人应用。</p><p>创建完成后，进入机器人管理后台，切换到「开发设置」页面：</p><img src="'+m+'" alt="切换到开发设置" width="40%"><p>在页面中可以看到应用的 <code>AppID</code> 和 <code>AppSecret</code>。使用凭证方式连接海豹时需要这两项；旧版文档中的 Token 字段已经弃用。</p><p><img src="'+c+'" alt="开发设置"></p><p>然后在「开发设置 IP 白名单」一栏中，填写你骰子所在电脑的 <strong>公网</strong> IP。（使用云服务器时，请填写对应云服务商在控制台提供的 IP）</p><img src="'+f+'" alt="连接官方 Bot" width="100%"><div class="warning custom-block"><p class="custom-block-title">注意：家庭网络的 IP 变动</p><p>如果你使用的是家用网络，在本地电脑运行海豹，要注意家庭网络的 IP 通常是不固定的，运营商随时可能会更换你的 IP，遇到问题时请先检查。</p></div>',12)),a("h2",P,[t[14]||(t[14]=e("连接海豹 ",-1)),l(o,{type:"tip",text:"v1.6.0"}),t[15]||(t[15]=e()),t[16]||(t[16]=a("a",{class:"header-anchor",href:"#连接海豹","aria-label":'Permalink to "连接海豹 <Badge type="tip" text="v1.6.0" />"'},"​",-1))]),t[19]||(t[19]=s('<p>登录海豹并添加账号，平台选择「QQ」，连接方式选择「QQ 官方机器人」。v1.6.0 提供两种登录方式：</p><ul><li><strong>二维码登录</strong>：不手工填写 AppID 和 AppSecret，按页面提示生成二维码并扫码绑定。扫码完成后，海豹会取得应用凭证并自动建立连接。二维码过期、绑定失败或检测到同一应用已存在时，需要删除失败连接后重试。</li><li><strong>应用凭证登录</strong>：填写 QQ 开放平台提供的 AppID 和 AppSecret。此方式适合需要明确管理应用凭证或配置 Webhook 的部署。</li></ul><img src="'+u+'" alt="连接官方 Bot" width="100%"><h3 id="websocket-与-webhook" tabindex="-1">WebSocket 与 Webhook <a class="header-anchor" href="#websocket-与-webhook" aria-label="Permalink to &quot;WebSocket 与 Webhook&quot;">​</a></h3><p>WebSocket 由海豹主动连接 QQ 官方服务，适合本机和大多数普通部署。Webhook 由 QQ 官方向海豹推送事件，适合已有公网 HTTPS 入口和反向代理的服务器部署。</p><p>选择 Webhook 时，需要在海豹连接表单中填写监听端口和回调路径，并在 QQ 开放平台配置与之对应的公网回调地址。公网入口、HTTPS 证书和反向代理由部署者维护；不要直接把海豹的管理端口暴露到公网。</p><h2 id="指令配置" tabindex="-1">指令配置 <a class="header-anchor" href="#指令配置" aria-label="Permalink to &quot;指令配置&quot;">​</a></h2><ol><li>进入「发布配置」页面；</li><li>点击「功能配置」；</li><li>点击「指令配置」；</li><li>再点击右上角的「重新配置」开始编辑；</li><li>点开「指令」页添加指令，「指令名」里面输入对应指令（例如 <code>r</code>、<code>ra</code>、<code>en</code>），<code>/</code> 是 QQ 官方机器人默认的指令前缀（海豹也支持使用 <code>/</code>）；</li><li>然后在「指令介绍」一栏填写指令的简介；</li><li>然后在「使用场景」一栏点击「QQ 频道」、「频道私信」、「QQ 群」，切记不能选中「消息列表」；</li><li>确认配置完成后，扫码确认修改，就可以完成指令配置。</li></ol><img src="'+Q+'" alt="进入指令配置页"><img src="'+q+'" alt="进行指令配置"><details class="details custom-block"><summary>推荐指令列表模版</summary><img src="'+b+'" alt="推荐指令列表模版1" width="66%"><img src="'+h+'" alt="推荐指令列表模版2" width="66%"></details><h2 id="机器人上线" tabindex="-1">机器人上线 <a class="header-anchor" href="#机器人上线" aria-label="Permalink to &quot;机器人上线&quot;">​</a></h2><p>点开「使用范围和人员页面」，进入「编辑」页，参考下面图片中编辑使用范围与人员。</p><img src="'+g+'" alt="连接官方 Bot"><p>配置完成后，点击「发布配置」页面，上传「自测报告」与「隐私协议」。</p><details class="details custom-block"><summary>「隐私协议」与「自测报告」模板</summary><p>这里提供了海豹骰的机器人「隐私协议」与「自测报告」模版。</p><p><strong>强烈建议你按自身情况进行修改，绝对不要原样上传，这涉及到你的机器人是否能被 QQ 官方的工作人员审核通过。</strong></p><p><a href="https://github.com/sealdice/sealdice-manual-next/blob/main/assets/%E6%9C%BA%E5%99%A8%E4%BA%BA%E8%87%AA%E6%B5%8B%E6%8A%A5%E5%91%8A.xlsx?raw=true" target="_blank" rel="noreferrer">机器人自测报告.xlsx</a></p><p><a href="https://github.com/sealdice/sealdice-manual-next/blob/main/assets/%E7%AC%AC%E4%B8%89%E6%96%B9%E6%9C%BA%E5%99%A8%E4%BA%BA%E9%9A%90%E7%A7%81%E4%BF%9D%E6%8A%A4%E6%8C%87%E5%BC%95.docx?raw=true" target="_blank" rel="noreferrer">第三方机器人隐私保护指引.docx</a></p><p>如果你对「指令列表」的指令进行了修改，或者新增了其他功能，请自行修改，需要在「预期输出」一栏填「指令简介」。</p></details><p>点击「提交审核」后，等待 QQ 官方人员测试并审核（时间不定）。审核通过后，在「发布设置」页面中点击「上线机器人」。</p><div class="tip custom-block"><p class="custom-block-title">提示：关于 QQ 审核</p><p>目前 QQ 审核主要是测试机器人能否在所选支持的场景下，正常回应指令列表里的指令（在没有添加任何其他内容前提下），为人工审核。</p><p>在提交审核前，请善用沙盒群，测试你提交的自测报告中，所提到的指令是否都能正常工作，机器人需要正常发出回应。</p><p>如果你的指令包含一些需要填写的参数，请务必在「自测报告」表格「特殊说明」一栏里补充说明。（你可以参考模板中对 <code>.ra</code> <code>.sc</code> <code>.en</code> 指令的特殊说明。）</p><p>如果审核未通过，点击右上角的「通知」查看原因，解决后再次提交。 如果实在无法解决，可加入「QQ 机器人官方频道」，在「寻求｜｜审核和及 bug 」一栏里，发帖询问。</p></div><h2 id="使用海豹" tabindex="-1">使用海豹 <a class="header-anchor" href="#使用海豹" aria-label="Permalink to &quot;使用海豹&quot;">​</a></h2><p>点击「使用人员与范围」页面，查看你的机器人对应的邀请二维码，扫码添加即可。</p><div class="warning custom-block"><p class="custom-block-title">平台限制</p><p>v1.6.0 已支持普通群消息、群内非 <code>@</code> 消息和 C2C 单聊，但应用必须在 QQ 开放平台取得对应场景和事件权限。收不到某类消息时，先检查应用的发布范围、事件订阅和审核状态。</p><p>QQ 官方接口存在消息频率、被动回复时限和媒体发送限制。海豹会拆分部分长消息，但密集发送、合并转发或某些本地媒体仍可能被平台拒绝；实际表现以开放平台返回的错误和当前权限为准。</p></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>大部分事项 <a href="https://bot.q.qq.com/wiki" target="_blank" rel="noreferrer">QQ 机器人文档</a> 都有说明，这里补充一些文档中没有说明的其他事项：</p><h3 id="企业账号的开发者资质审核" tabindex="-1">企业账号的开发者资质审核 <a class="header-anchor" href="#企业账号的开发者资质审核" aria-label="Permalink to &quot;企业账号的开发者资质审核&quot;">​</a></h3><p>如果你使用企业账号进行了注册，请记得在资料一栏中进行开发者资质状态审核。该审核需要将对应企业的银行卡号上传至腾讯审核，期间的等待时间可能较久。在开发者资质状态通过后，你才能将官方机器人送审。</p><img src="'+k+'" alt="开发者资质状态审核"><h3 id="机器人官方频道跳转" tabindex="-1">机器人官方频道跳转 <a class="header-anchor" href="#机器人官方频道跳转" aria-label="Permalink to &quot;机器人官方频道跳转&quot;">​</a></h3><p>机器人「资料卡」页面中资料卡设置一栏中，「机器人官方频道跳转」不能是骰子的「沙盒频道」。</p><img src="'+x+'" alt="机器人官方频道跳转"><h3 id="功能审核未通过" tabindex="-1">功能审核未通过 <a class="header-anchor" href="#功能审核未通过" aria-label="Permalink to &quot;功能审核未通过&quot;">​</a></h3><p>有时候「功能配置」页面中，「功能配置与提审」旁显示审核通过，但实际并没有通过，这时点击「机器人上线」的会显示发送错误。</p><p>遇见这种情况请点击「通知」，看机器人哪方面没过审，修改后再次提交审核。</p>',32))])}const D=i(A,[["render",E]]);export{I as __pageData,D as default};
